# Create the output directory if it doesn't exist
file mkdir outputs

# Open the output file
set output_file [open outputs/unloaded_nets.txt w]

# Get all nets in the design
set all_nets [get_nets *]

foreach net $all_nets {
    # Skip special nets like VDD, VSS, etc., if necessary, but the task asks for "every signal net"
    # We will check all nets.

    # Get all pins connected to this net
    set pins [get_pins -of_objects $net]

    # Find the driver pin (output direction)
    set driver_pin ""
    foreach pin $pins {
        set direction [get_property direction $pin]
        if { $direction == "output" } {
            set driver_pin $pin
            break
        }
    }

    # If there is no driver, skip this net
    if { $driver_pin eq "" } {
        continue
    }

    # Find if there are any loads (input pins or input ports)
    set has_load 0

    # Check for input pins
    foreach pin $pins {
        set direction [get_property direction $pin]
        if { $direction == "input" } {
            set has_load 1
            break
        }
    }

    # If no input pins found, check for input ports
    if { $has_load == 0 } {
        set ports [get_ports -of_objects $net]
        foreach port $ports {
            set direction [get_property direction $port]
            if { $direction == "input" } {
                set has_load 1
                break
            }
        }
    }

    # If no load is found, record the net
    if { $has_load == 0 } {
        # Get the driver instance name
        set driver_inst [get_property INSTANCE $driver_pin]
        set driver_pin_name [get_property NAME $driver_pin]
        set net_name [get_property NAME $net]

        # Format: <net_name> <driver_instance>/<driver_pin>
        puts $output_file "$net_name $driver_inst/$driver_pin_name"
    }
}

# Close the output file
close $output_file

